from scipy import ndimage
def solve(I):
    I=np.array(I); O=I.copy(); H,W=I.shape
    mask=(I==3)
    lab,n=ndimage.label(mask)  # 4-connectivity
    boxes={}
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        boxes[i]=(ys.min(),ys.max(),xs.min(),xs.max())
    for y,x in np.argwhere(I==2):
        inbox=False
        for (y0,y1,x0,x1) in boxes.values():
            if y0<=y<=y1 and x0<=x<=x1: inbox=True;break
        if not inbox: continue
        for dy in(-1,0,1):
            for dx in(-1,0,1):
                if dy==0 and dx==0: continue
                yy,xx=y+dy,x+dx
                if 0<=yy<H and 0<=xx<W and I[yy,xx]!=2:
                    O[yy,xx]=1
    return O
